TRANSLATOR(vfwarith)
{
	// P10/P10b: the direct widening route, arithmetic and fused. Every form it refuses -- an
	// unobserved vtype, an overlap 5.2 does not permit, either family with its switch off -- still
	// reaches the helper below unchanged. (Masked forms, tu/mu, mf2 and vstart != 0 are ADMITTED;
	// LMUL 8 and e64 widening are not refusals at all, they are illegal encodings both paths
	// reject.) The widening REDUCTIONS never arrive here: they decode to `vfwred`.
	if (config::rvv_direct) {
		dbt::rv32::VType const vt{rvv_bb_vtype};
		u16 cb = 64;
		if (u8 const chunks = RvvQcgTypedFWidenAdmit(i.raw, vt, &cb); chunks) {
			RvvEmitTypedFWidenChunkGroup(i.raw, vt, chunks, cb);
			return;
		}
		// Order item 4: the LLVM arm. At most one of the two can fire -- the QCG predicate
		// refuses `aot_use_llvm` and this one requires `RvvLLVMTypedSubstrate()`, which
		// requires it -- so this is a backend selection and not a widening of the envelope.
		if (u8 const chunks = RvvLLVMFWidenAdmit(i.raw, vt, &cb); chunks) {
			RvvEmitTypedFWidenChunkGroup(i.raw, vt, chunks, cb);
			return;
		}
	}
	TranslateHelper(i, RuntimeStubId::id_rv32_vfwarith);
}
